/**
 * The server-side default AI run configuration for the current user in the current project —
 * the user's per-project preference over the project default, as resolved by the tasks backend.
 * Composers read it to show what a run launches with when nothing is picked; a run created
 * without an explicit selection gets the same defaults applied server-side.
 */
export const taskRunDefaultsLogic = kea<taskRunDefaultsLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'taskRunDefaultsLogic']),

    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),

    loaders(({ values }) => ({
        myConfig: {
            __default: null as TasksUserConfigResponseApi | null,
            loadMyConfig: async (): Promise<TasksUserConfigResponseApi | null> => {
                if (values.currentProjectId == null) {
                    return null
                }
                try {
                    return await tasksMeConfigList(String(values.currentProjectId))
                } catch {
                    // Defaults are a nicety — a failed fetch (missing scope, transient error) must never
                    // break the composer, which falls back to its built-in defaults.
                    return null
                }
            },
        },
    })),

    selectors({
        resolvedDefaults: [
            (s) => [s.myConfig],
            (myConfig: TasksUserConfigResponseApi | null): TasksResolvedAIRunDefaultsApi | null =>
                myConfig?.resolved_ai_run_defaults ?? null,
        ],
        // Whatever runtime the default names: the composer's pickers are runtime-aware (they scope the
        // permission modes to the selected model's harness), so a Codex default renders as readily as a
        // Claude one. Filtering by adapter here would drop the preference to the built-in model rather
        // than to the next level that configured one, which reads as the setting being ignored.
        defaultModel: [
            (s) => [s.resolvedDefaults],
            (defaults: TasksResolvedAIRunDefaultsApi | null): string | null => defaults?.model ?? null,
        ],
        defaultEffort: [
            (s) => [s.resolvedDefaults],
            (defaults: TasksResolvedAIRunDefaultsApi | null): string | null => defaults?.reasoning_effort ?? null,
        ],
        // The server already resolved which runtime the default belongs to; carrying it beats
        // re-deriving from the client catalogue, which can be stale and mislabel the harness.
        defaultRuntimeAdapter: [
            (s) => [s.resolvedDefaults],
            (defaults: TasksResolvedAIRunDefaultsApi | null): string | null => defaults?.runtime_adapter ?? null,
        ],
    }),

    afterMount(({ actions }) => {
        actions.loadMyConfig()
    }),
])
